{
  "technical_and_design_decisions": [
    "For U1, we will integrate the Hortonworks Connector for Teradata by adding it as a Maven dependency and extending the Sqoop command parser to support the --connection-manager parameter with the TeradataConnManager class. The NPE in the direct JDBC driver approach will not be fixed as the user story explicitly states the Hortonworks solution works.",
    "For U2, we will introduce a new configuration property (e.g., xd.log.dir) that defaults to ${xd.home}/logs but can be overridden via system property or environment variable. All logging configurations (logback.xml, etc.) will be updated to reference this property.",
    "For U3 and U5, we will create a new repository spring-bus and extract the message-bus and serialization codec modules into it as separate Maven submodules. The original Spring XD repository will depend on the released spring-bus artifacts.",
    "For U4, we will extract the input/output type conversion module into the existing spring-cloud-dataflow repository (or a new submodule if appropriate).",
    "For U6, we will implement a new Admin SPI class that uses ModuleLauncher to run modules in a single JVM, managing module lifecycle via threads and in-memory communication.",
    "For U7, we will implement an Admin SPI that communicates with Diego's Receptor API to launch and manage modules as LRP (Long Running Processes) on Cloud Foundry.",
    "For U8, we will investigate using Spring Cloud Service Discovery (e.g., Eureka client) to enable self-registration of modules. A prototype will be built and integrated into the Spring XD runtime on CF."
  ],
  "assumptions": [
    "The development team has full access to the existing Spring XD source code, build system (Maven/Gradle), and CI/CD pipelines.",
    "All new repositories (spring-bus, etc.) will be hosted on a platform like GitHub and artifacts will be published to a Maven repository (e.g., Maven Central or internal repo).",
    "The existing Spring XD test suite is available and can be run to verify compatibility after extractions.",
    "Work is performed by a single developer; estimates are in work-hours and do not account for calendar time or parallel work.",
    "Effort estimates include analysis, coding, unit/integration testing, and documentation for each activity.",
    "No major refactoring of existing code beyond the scope of the user stories is required.",
    "The Diego Receptor API is stable and accessible; we assume adequate documentation is available.",
    "For U8, we assume Spring Cloud Eureka is available as a service registry; the investigation may conclude with a recommendation rather than full production integration."
  ],
  "activities": [
    {
      "activity_id": "ACT-001",
      "activity_name": "Teradata Sqoop integration (U1)",
      "activity_description": "Analyze current Sqoop command handling, add Hortonworks Teradata connector dependency, modify import command to support --connection-manager for Teradata, write integration tests, update documentation.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-002",
      "activity_name": "Configurable logging directory (U2)",
      "activity_description": "Analyze current logging configuration, introduce xd.log.dir property with default, update all logging configurations, test and document.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-003",
      "activity_name": "Extract message-bus to spring-bus (U3)",
      "activity_description": "Identify and extract message-bus module code from Spring XD into new spring-bus repository, set up build and CI, update Spring XD dependency, run integration tests.",
      "most_likely_effort": 100
    },
    {
      "activity_id": "ACT-004",
      "activity_name": "Extract type conversion to spring-cloud-dataflow (U4)",
      "activity_description": "Identify and extract input/output type conversion module from Spring XD into spring-cloud-dataflow repository, set up build and CI, update Spring XD dependency, run integration tests.",
      "most_likely_effort": 80
    },
    {
      "activity_id": "ACT-005",
      "activity_name": "Extract serialization codec to spring-bus (U5)",
      "activity_description": "Identify and extract serialization codec module from Spring XD into spring-bus repository (same repo as ACT-003), update Spring XD dependency, run integration tests.",
      "most_likely_effort": 60
    },
    {
      "activity_id": "ACT-006",
      "activity_name": "Singlenode Admin SPI implementation (U6)",
      "activity_description": "Design and implement a new Admin SPI class that uses ModuleLauncher to run modules in a single JVM. Handle lifecycle, in-process communication, error handling. Write unit and integration tests.",
      "most_likely_effort": 100
    },
    {
      "activity_id": "ACT-007",
      "activity_name": "Diego-based Receptor Admin SPI implementation (U7)",
      "activity_description": "Design and implement an Admin SPI that uses the Diego Receptor API to launch and manage modules on Cloud Foundry. Implement task submission, status polling, cancellation. Write tests with mocking. Document usage.",
      "most_likely_effort": 120
    },
    {
      "activity_id": "ACT-008",
      "activity_name": "Service self-registration investigation and prototype (U8)",
      "activity_description": "Research service discovery solutions (e.g., Eureka, Consul), design self-registration approach for Spring XD modules on CF, prototype with a simple module, document findings and recommendations.",
      "most_likely_effort": 60
    },
    {
      "activity_id": "ACT-009",
      "activity_name": "Overall integration testing and documentation",
      "activity_description": "Perform cross-story integration testing, fix any issues found, and produce final documentation (READMEs, setup guides) for all new features and extractions.",
      "most_likely_effort": 40
    }
  ],
  "reported_total": {
    "most_likely_effort": 606
  }
}

